"""Validation for a Peg's search representation.

A Peg's ``search`` block — how its rows read in Workpeg's universal search —
is authored in ``workpeg.json`` (the peg-level config, alongside ``function``
and ``runtime``). It is three optional templates:

    {
      "search": {
        "label": "{needle} in {table.name}: {haystack}",
        "link":  "{domain}/b/{business}/invoice/{row}",
        "icon":  "cash"
      }
    }

This module is the single validator the build runs over that block, so a
Peg learns at build time — not silently at render — when a ``link`` could run
script or leave the platform. The server (``core.links.is_safe_link``) enforces
the identical rule when it renders a hit.

The deprecated UI ``SearchManifest`` class routes through the compiler's own
port of that rule, so both authoring paths agree on what is legal.

**Two ports, and this is the one on the live road.** That sentence used to
read "so the two can never drift", and they had: the compiler's
``_is_safe_search_link`` grew a tab/newline strip and a backslash
normalisation, and this copy — the one every ``workpeg.json`` passes through
— did not. A build accepted ``https://evil.example\\.workpeg.com/x``, whose
host a browser reads as ``evil.example``. ``tests/ui/test_search_manifest.py``
now pins BOTH ports against the server's, which is what the old sentence
claimed without anything holding it up.
"""
import re
from urllib.parse import urlparse

#: The keys a search manifest may declare — mirrors the server's MANIFEST_KEYS.
KEYS = ("label", "link", "icon")

#: The platform's own base domain; a rendered ``https`` hit link may only point
#: here (that is what ``{domain}`` expands to).
PLATFORM_DOMAIN = "workpeg.com"

#: A ``{variable}`` placeholder in a template.
_VAR_RE = re.compile(r"\{[a-z][a-z._]*\}")

#: A Tabler icon name.
_ICON_RE = re.compile(r"[a-z0-9-]+")

#: The characters a URL parser DELETES from anywhere in its input before it
#: parses: ASCII tab, line feed and carriage return (WHATWG URL, "remove all
#: ASCII tab or newline"). Mirrors ``core.links._URL_DELETED`` server-side.
_URL_DELETED = {0x09: None, 0x0A: None, 0x0D: None}


class ManifestValidationError(ValueError):
    """A ``search`` block that would render an unsafe or malformed manifest."""


def _is_safe_link(href: str) -> bool:
    """Whether a *rendered* hit href may be handed to the client — a faithful
    port of the server's ``core.links.is_safe_link``. Safe iff an in-app
    relative path (``/…`` but not ``//host`` or ``/\\host``) or an ``https``
    URL on the platform base domain; everything else (``javascript:``/
    ``data:``, ``//evil``, off-platform https) is rejected.

    The two normalisations below are not decoration. This function judges the
    string the BROWSER will parse, not the one that was typed, and without
    them the suffix test at the end reads a link as on-platform that a browser
    resolves off it.
    """
    if not href:
        return False
    # Tab/LF/CR are DELETED from anywhere in a URL before it is parsed, so the
    # link that gets followed is not always the link that was written:
    # "/<TAB>/evil.example" is fetched as "//evil.example" while the offset
    # test below still sees a single leading "/".
    href = href.translate(_URL_DELETED)
    if not href:
        return False
    # Same principle over the whole string: a URL parser reads U+005C as
    # U+002F everywhere in a special-scheme URL's authority, so the host ends
    # at the FIRST backslash. urlparse does not — it keeps the backslash in
    # the hostname — and the host test below is a suffix match, so
    # "https://evil.example\.workpeg.com/x" read as safe here while a browser
    # resolves it to host "evil.example". Normalise before judging.
    href = href.replace("\\", "/")
    if href.startswith("/"):
        # Second character, not a "//" prefix: browsers resolve "/\evil.com"
        # as protocol-relative too, so a "//" check alone lets an origin
        # through wearing a path's clothes.
        return href[1:2] not in ("/", "\\")
    try:
        parts = urlparse(href)
    except ValueError:
        # A malformed URL ("https://[oops/1" -> "Invalid IPv6 URL") is not a
        # safe link; it must read as False here, not crash the build with a
        # traceback. The server's urlsplit raises the same way and its caller
        # treats it as unsafe, so this keeps the two ports agreeing.
        return False
    if parts.scheme != "https":
        return False
    host = parts.hostname or ""
    return host == PLATFORM_DOMAIN or host.endswith("." + PLATFORM_DOMAIN)


def check_link(template: str) -> None:
    """Reject a ``link`` template that could render to an unsafe href.

    Render it with safe placeholders (``{domain}`` -> the platform origin,
    every other ``{var}`` -> a token) and apply the same test the server
    applies at render time, so a build fails on a link the server would drop.
    """
    # Both origin variables expand to a platform origin server-side, so they
    # stand in as one here; every other {var} becomes an opaque token.
    rendered = template.replace("{domain}", "https://peg." + PLATFORM_DOMAIN)
    rendered = rendered.replace(
        "{workspace}", "https://space." + PLATFORM_DOMAIN)
    rendered = _VAR_RE.sub("x", rendered)
    if _is_safe_link(rendered):
        return
    raise ManifestValidationError(
        f"search link {template!r} is not safe — a hit's link must be a "
        f'relative path ("/…") or start with {{domain}} and stay on '
        f"{PLATFORM_DOMAIN}, so a search result can never run script or send "
        f"a searcher off-site."
    )


def validate(block) -> "dict[str, str]":
    """Validate a ``search`` block and return the declared keys only.

    Accepts the same shape the server ingests: a mapping of
    ``label``/``link``/``icon`` to non-empty template strings, each optional.
    Raises :class:`ManifestValidationError` on anything else — an unknown key,
    a non-string value, an unsafe link, a malformed icon name.
    """
    if not isinstance(block, dict):
        raise ManifestValidationError(
            "the 'search' block in workpeg.json must be an object with "
            "label / link / icon keys")
    manifest: "dict[str, str]" = {}
    for key, value in block.items():
        if key not in KEYS:
            raise ManifestValidationError(
                f"unexpected key {key!r} in the search block — "
                f"only {', '.join(KEYS)} are allowed")
        if not isinstance(value, str) or not value.strip():
            raise ManifestValidationError(
                f"search {key} must be a non-empty template string")
        manifest[key] = value
    if "link" in manifest:
        check_link(manifest["link"])
    if "icon" in manifest and not _ICON_RE.fullmatch(manifest["icon"]):
        raise ManifestValidationError(
            f"search icon {manifest['icon']!r} is not a lowercase Tabler icon "
            'name (e.g. "cash", "file-text")')
    return manifest
